/* Canonical, dependency-free network Statistics UI. Live errors never load demo data. */
(() => {
  'use strict';
  const language=()=>globalThis.NodusI18n?.language?.()==='en'?'en':'fi';
  const l=(fi,en)=>language()==='en'?en:fi;
  const locale=()=>language()==='en'?'en-GB':'fi-FI';
  const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const number=(value,maximumFractionDigits=0)=>value!==null&&value!==undefined&&value!==''&&Number.isFinite(Number(value))?new Intl.NumberFormat(locale(),{maximumFractionDigits}).format(Number(value)):'—';
  const array=value=>Array.isArray(value)?value:[];
  const date=(value,short=false)=>{if(value===null||value===undefined||value==='')return '—';const d=new Date(value);return Number.isFinite(d.getTime())?new Intl.DateTimeFormat(locale(),short?{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'Europe/Helsinki'}:{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',timeZone:'Europe/Helsinki'}).format(d):'—';};
  function rawAmount(value,decimals=8){
    if(value===null||value===undefined||!/^\d+$/.test(String(value)))return '—';
    const digits=String(value).replace(/^0+(?=\d)/,''),padded=digits.padStart(decimals+1,'0');
    const whole=padded.slice(0,-decimals),fraction=padded.slice(-decimals).replace(/0+$/,'');
    const grouped=BigInt(whole).toLocaleString(locale());
    return grouped+(fraction?(language()==='en'?'.':',')+fraction:'');
  }
  const shorten=(value,n=12)=>{const s=String(value??'');return s.length>n*2+3?`${s.slice(0,n)}…${s.slice(-7)}`:s;};
  const state={tab:'overview',range:'24h',role:'all',search:'',selected:null,delegationPage:0,data:null,dataRange:null,loading:false,error:false,demo:false,exporting:false,exportError:false};
  let root=null,options={},request=null,requestId=0,refreshTimer=null;
  const tabs=()=>[['overview',l('Yhteenveto','Overview')],['activity',l('Aktiivisuus','Activity')],['nodes',l('Nodet ja kartta','Nodes & map')],['staking',l('Staking ja storage','Staking & storage')],['contracts',l('Älysopimukset','Contracts')]];
  const ranges=()=>[['24h','24 h'],['7d',l('7 vrk','7 d')],['30d',l('30 vrk','30 d')],['1y',l('1 vuosi','1 y')],['all',l('Kaikki','All')]];
  globalThis.NodusI18n?.addMessages?.({'Tilastot':'Statistics','Verkon tilastot ja havaintohistoria':'Network statistics and observation history','NODUS TESTNET · VAIN LUKU':'NODUS TESTNET · READ ONLY','Tilastojen tiedostot puuttuvat. Päivitä asennus.':'Statistics files are missing. Update the installation.'});
  const isActive=()=>root&&(!globalThis.location||globalThis.location.hash==='#statistics');
  const opLabel=op=>({spend:l('Rahansiirrot','Transfers'),claim:l('Lunastukset','Claims'),stake:l('Staking','Staking'),delegate:l('Delegoinnit','Delegations'),unstake:l('Panoksen vapautukset','Unstaking'),undelegate:l('Delegoinnin poistot','Undelegation'),evm_call:l('Sopimuskutsut','Contract calls'),evm_create:l('Sopimusten julkaisut','Contract deployments'),evm_deposit:l('EVM-talletukset','EVM deposits'),evm_withdraw:l('EVM-nostot','EVM withdrawals'),evm_redeem:l('EVM-lunastukset','EVM redemptions'),name_register:l('Nimirekisteröinnit','Name registrations'),chain_config:l('Ketjuasetukset','Chain configuration'),token_create:l('Tokenien julkaisut','Token creation'),storage_register:l('Storage-rekisteröinnit','Storage registrations'),storage_exit:l('Storagen poistumiset','Storage exits'),storage_report:l('Storage-raportit','Storage reports')})[op]||String(op||l('Muu tapahtuma','Other operation'));
  const roleLabel=role=>({witness:'Witness',validator:'Witness',storage:'Storage',peer:l('Verkkonode','Peer')})[role]||String(role);
  const statusLabel=status=>({active:l('Aktiivinen','Active'),committee:l('Komitean jäsen','Committee member'),eligible:l('Ehdolla','Eligible'),exiting:l('Poistumassa','Exiting'),released:l('Vapautettu','Released'),observed:l('Havaittu','Observed'),unknown:l('Tuntematon','Unknown'),unreachable:l('Ei tavoitettu','Unreachable'),online:l('Tavoitettu','Reachable')})[status]||l('Havaittu','Observed');
  const empty=(title,body)=>`<div class="stats-empty"><div><strong>${esc(title)}</strong>${esc(body)}</div></div>`;
  const panelHead=(title,subtitle='',badge='')=>`<div class="stats-panel-head"><div><h2>${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div>${badge?`<span class="stats-panel-badge">${esc(badge)}</span>`:''}</div>`;
  const metric=(label,value,note,cyan=false,unit='')=>`<article class="stats-kpi"><div class="stats-kpi-label">${esc(label)}</div><strong class="stats-kpi-value${cyan?' cyan':''}">${esc(value)}${unit?`<small>${esc(unit)}</small>`:''}</strong><div class="stats-kpi-note">${esc(note)}</div></article>`;
  const note=(fi,en)=>`<p class="stats-note">${esc(l(fi,en))}</p>`;
  const facts=rows=>`<dl class="stats-facts">${rows.map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl>`;
  const activity=()=>array(state.data?.series?.activity);
  const network=()=>array(state.data?.series?.network);
  const tps=()=>array(state.data?.series?.tps);
  const summary=()=>state.data?.summary||{};
  const coverage=()=>state.data?.coverage||{};
  const timestamp=point=>point.timestamp??point.start_ms??point.time;
  const numeric=(point,key)=>{const value=point[key];return value!==null&&value!==undefined&&value!==''&&Number.isFinite(Number(value))?Number(value):null;};
  function chart(id,title,subtitle,points,series,{raw=false,unit='',foot='',gapMs=null}={}){
    const valid=array(points).filter(p=>p&&Number.isFinite(new Date(timestamp(p)).getTime()));
    let inner='';
    if(!valid.length||!valid.some(p=>series.some(s=>numeric(p,s.key)!==null))){
      inner=empty(l('Historiaa ei vielä ole','No history yet'),l('Käyrä ilmestyy, kun tältä aikaväliltä on havaintoja. Puuttuva tieto ei ole nolla.','This chart appears when observations cover the selected range. Missing data is not zero.'));
    }else{
      const width=700,height=220,left=53,right=18,top=13,bottom=36,plotW=width-left-right,plotH=height-top-bottom;
      const times=valid.map(p=>new Date(timestamp(p)).getTime()),minT=Math.min(...times),maxT=Math.max(...times);
      const scale=raw?1e8:1;
      const values=valid.flatMap(p=>series.map(s=>numeric(p,s.key))).filter(v=>v!==null).map(v=>v/scale);
      const maxY=Math.max(1,...values)*1.12;
      const expectedGap=gapMs??({"24h":3600000,"7d":21600000,"30d":86400000,"1y":604800000}[state.range]??86400000)*1.8;
      const x=i=>left+(maxT===minT?plotW/2:(times[i]-minT)/(maxT-minT)*plotW),y=v=>top+plotH-(v/scale/maxY)*plotH;
      const formatY=v=>v>=1e9?number(v/1e9,1)+'B':v>=1e6?number(v/1e6,1)+'M':v>=1e3?number(v/1e3,1)+'k':number(v,maxY<10?1:0);
      const grid=Array.from({length:4},(_,i)=>{const v=maxY*i/3,yy=top+plotH-plotH*i/3;return `<line x1="${left}" y1="${yy}" x2="${width-right}" y2="${yy}" class="stats-gridline"/><text x="${left-9}" y="${yy+3}" text-anchor="end">${esc(formatY(v))}</text>`;}).join('');
      const paths=series.map((s,j)=>{let path='',open=false;valid.forEach((p,i)=>{const v=numeric(p,s.key);if(v===null){open=false;return;}if(i>0&&times[i]-times[i-1]>expectedGap)open=false;path+=`${open?'L':'M'}${x(i).toFixed(1)},${y(v).toFixed(1)} `;open=true;});const isolated=valid.map((p,i)=>{const v=numeric(p,s.key);if(v===null)return '';const before=i>0&&numeric(valid[i-1],s.key)!==null&&times[i]-times[i-1]<=expectedGap,after=i<valid.length-1&&numeric(valid[i+1],s.key)!==null&&times[i+1]-times[i]<=expectedGap;return !before&&!after?`<circle cx="${x(i)}" cy="${y(v)}" r="2.7" fill="${s.color}"/>`:'';}).join('');return `<path class="stats-line" d="${path}" stroke="${s.color}"/>${isolated}`;}).join('');
      const ticks=[...new Set([0,Math.floor((valid.length-1)/2),valid.length-1])].map((i,j,a)=>`<text x="${x(i)}" y="${height-8}" text-anchor="${j===0?'start':j===a.length-1?'end':'middle'}">${esc(new Intl.DateTimeFormat(locale(),{day:'numeric',month:'short',hour:state.range==='24h'?'2-digit':undefined,timeZone:'Europe/Helsinki'}).format(new Date(times[i])))}</text>`).join('');
      const stride=Math.max(1,Math.ceil(valid.length/150));
      const hits=valid.map((p,i)=>{if(i%stride&&i!==valid.length-1)return '';const first=series.map(s=>numeric(p,s.key)).find(v=>v!==null);if(first===undefined)return '';const readout=date(timestamp(p),true)+' · '+series.map(s=>`${s.label}: ${raw?rawAmount(p[s.key]):number(p[s.key],s.decimals??0)}${unit?' '+unit:''}`).join(' · ');return `<g class="stats-chart-point" tabindex="0" role="img" aria-label="${esc(readout)}" data-chart-readout="${id}" data-value="${esc(readout)}"><title>${esc(readout)}</title><rect x="${x(i)-5}" y="${top}" width="10" height="${plotH}" fill="transparent"/><circle cx="${x(i)}" cy="${y(first)}" r="3.3" fill="${series[0].color}"/></g>`;}).join('');
      inner=`<div class="stats-chart-legend">${series.map(s=>`<span><i style="background:${s.color}"></i>${esc(s.label)}</span>`).join('')}${unit?`<span>${esc(unit)}</span>`:''}</div><div class="stats-chart"><svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${esc(title)}"><title>${esc(title)}</title>${grid}${paths}${ticks}${hits}</svg></div><div class="stats-chart-readout" id="${id}-readout" aria-live="polite">${esc(l('Osoita käyrää tai käytä sarkainnäppäintä.','Point at the chart or use the Tab key.'))}</div>`;
    }
    return `<section class="stats-panel">${panelHead(title,subtitle)}${inner}${foot?`<div class="stats-panel-foot">${esc(foot)}</div>`:''}</section>`;
  }
  function bars(title,subtitle,items,{raw=false}={}){
    const rows=array(items).filter(x=>x&&Number.isFinite(Number(x.count??x.value??x.amount_raw))).slice(0,12);
    const val=x=>Number(x.count??x.value??x.amount_raw),max=Math.max(1,...rows.map(val));
    return `<section class="stats-panel">${panelHead(title,subtitle)}${rows.length?`<div class="stats-bars">${rows.map((row,i)=>`<div class="stats-bar-row"><div class="stats-bar-label"><span>${esc(row.label??(row.pool?({1:'Storage',2:'Compute',3:'Bandwidth',4:l('Tulevat palvelut','Future services')}[row.pool]??l('Pooli','Pool')+' '+row.pool):opLabel(row.name??row.op??row.operation)))}</span><strong>${esc(raw?rawAmount(row.amount_raw??row.value):number(row.count??row.value))}${raw?' NODUS':''}</strong></div><div class="stats-bar-track"><span style="width:${Math.max(0,Math.min(100,val(row)/max*100))}%;background:${['#6dcfc5','#8cabda','#bccd8e','#b49ed4'][i%4]}"></span></div></div>`).join('')}</div>`:empty(l('Ei luokiteltuja tapahtumia','No classified operations'),l('Luokittelu täydentyy indeksoinnin edetessä.','The breakdown fills in as indexing progresses.'))}</section>`;
  }
  function mainMetrics(){const s=summary();return `<div class="stats-kpis">${metric(l('Tapahtumat / 24 h','Transactions / 24 h'),number(s.tx_24h),l('Täysi liukuva 24 tunnin kattavuus','Complete rolling 24-hour coverage'),true)}${metric(l('Aktiiviset osoitteet','Active addresses'),number(s.active_native_addresses),l('Native · indeksoitu aikaväli','Native · indexed range'))}${metric(l('Aktiiviset witnessit','Active witnesses'),number(s.active_validators),l('Ketjun validaattorit','Chain validators'))}${metric(l('Storage-nodet','Storage nodes'),number(s.storage_nodes),l('Nykyisen epochin jäsenet','Current epoch set members'))}</div>`;}
  function overview(){
    const s=summary(),points=activity(),hasIndexed=points.some(p=>p.transactions!==null&&p.transactions!==undefined);
    const rows=hasIndexed?points:tps().map(p=>({...p,transactions:p.transactions??p.tx}));
    return mainMetrics()+`<div class="stats-grid">${chart('overview-activity',l('Verkon aktiivisuus','Network activity'),hasIndexed?l('Indeksoidut tapahtumat aikajaksoittain','Indexed transactions by time bucket'):l('Scanin valmis 24 tunnin aikasarja','Scan’s built-in 24-hour time series'),rows,[{key:'transactions',label:l('Tapahtumat','Transactions'),color:'#6edace'}],{foot:l('Tapahtumat sisältävät myös sopimuskutsuja ja stakingia. Tavalliset rahansiirrot näkyvät erikseen Aktiivisuus-välilehdellä.','Transactions also include contract calls and staking. Simple transfers are shown separately in Activity.')})}<section class="stats-panel">${panelHead(l('Verkon tilanne','Network at a glance'),l('Viimeisimmät käytettävissä olevat havainnot','Latest available observations'),'TESTNET')}${facts([[l('TPS · viimeinen minuutti','TPS · last minute'),number(s.tps_1m,2)],[l('TPS · viimeinen tunti','TPS · last hour'),number(s.tps_1h,2)],[l('Sidotut validaattorit','Bonded validators'),number(s.bonded_validators)],[l('Havaitut nodet','Observed nodes'),number(s.observed_nodes)],[l('Kiertävä NODUS','Circulating NODUS'),rawAmount(s.circulating_raw)],[l('Palkkiopooli · NODUS','Reward pool · NODUS'),rawAmount(s.reward_pool_raw)]])}<div class="stats-panel-foot">${esc(l('Witness-, storage- ja verkkoroolit voivat kuulua samalle nodelle. Roolimääriä ei summata verkon kokonaismääräksi.','Witness, storage and peer roles can belong to the same node. Role counts are not added up to a network total.'))}</div></section></div><div class="stats-grid equal">${chart('overview-addresses',l('Osoitteiden aktiivisuus','Address activity'),l('Uniikit osoitteet aikajaksoittain · lähdekattavuuden sisällä','Unique addresses per bucket · within indexed coverage'),points,[{key:'active_native_addresses',label:'Native',color:'#88aef0'},{key:'active_evm_addresses',label:'EVM',color:'#c7a4e8'}],{foot:l('Osoite ei tarkoita ihmistä tai luotua lompakkoa. Native- ja EVM-lukuja ei yhdistetä uniikeiksi käyttäjiksi.','An address is not a person or a created wallet. Native and EVM counts are not combined into unique users.')})}${bars(l('Tapahtumalajit','Operation mix'),l('Valittu aikaväli · indeksoitu aineisto','Selected range · indexed data'),state.data?.breakdown?.operations)}</div>`;
  }
  function activityView(){const p=activity(),s=summary();return `<div class="stats-kpis">${metric(l('Tapahtumat / aikaväli','Transactions / selected range'),number(s.transactions),l('Indeksoidun aineiston hyväksytyt tapahtumat','Applied transactions in indexed data'),true)}${metric(l('Rahansiirrot','Transfers'),number(s.spends),l('Native spend · indeksoitu aikaväli','Native spend · indexed range'))}${metric(l('Siirretty NODUS','Transferred NODUS'),rawAmount(s.transfer_raw),l('Tunnetut ulkoiset vastaanottajat · vaihtoraha pois','Known external recipients · change excluded'))}${metric(l('Keskimääräinen lohkoväli','Average block interval'),s.avg_block_ms===null||s.avg_block_ms===undefined?'—':number(Number(s.avg_block_ms)/1000,2),l('Indeksoitu aikaväli','Indexed range'),false,'s')}</div>`+`<div class="stats-grid equal">${chart('activity-transfers',l('Siirrot ja sopimuskutsut','Transfers and contract calls'),l('Tapahtumalajit eroteltuina','Operations shown separately'),p,[{key:'spends',label:l('Rahansiirrot','Transfers'),color:'#6edace'},{key:'evm_calls',label:l('Sopimuskutsut','Contract calls'),color:'#c6a3ef'}])}${chart('activity-addresses',l('Aktiiviset osoitteet','Active addresses'),l('Aikajakson erilliset native- ja EVM-osoitteet','Distinct native and EVM addresses per bucket'),p,[{key:'active_native_addresses',label:'Native',color:'#82aef7'},{key:'active_evm_addresses',label:'EVM',color:'#c6a3ef'}])}</div><div class="stats-grid equal">${chart('activity-blocks',l('Lohkot ja lohkoväli','Blocks and block timing'),l('Lohkoja aikajaksossa','Blocks per time bucket'),p,[{key:'blocks',label:l('Lohkot','Blocks'),color:'#a6cf91'}])}${chart('activity-fees',l('Maksetut tapahtumakulut','Transaction fees paid'),l('Tarkat summat osoittamalla käyrää','Exact amounts in chart readouts'),p,[{key:'fee_raw',label:l('Kulut','Fees'),color:'#e2be82'}],{raw:true,unit:'NODUS'})}</div><div class="stats-grid equal">${chart('activity-volume',l('Native-siirtovolyymi','Native transfer volume'),l('Vaihtoraha ja tuntemattomat lähtöosoitteet huomioidaan','Change and unresolved sender addresses are handled explicitly'),p,[{key:'transfer_raw',label:l('Siirretty','Transferred'),color:'#6edace'}],{raw:true,unit:'NODUS',foot:l('Jos lähtöosoitetta ei tunneta, kokonaismäärä jää tuntemattomaksi. Osittainen aineisto ei ole koko verkon volyymi.','If a sender is unresolved, the complete amount stays unknown. Partial data is not the whole network’s volume.')})}${chart('activity-timing',l('Lohkovälin kehitys','Block interval over time'),l('Keskimääräinen lohkoväli aikajaksoittain','Average block interval per bucket'),p.map(point=>({...point,avg_block_seconds:point.avg_block_ms===null||point.avg_block_ms===undefined?null:Number(point.avg_block_ms)/1000})),[{key:'avg_block_seconds',label:l('Lohkoväli','Block interval'),color:'#a6cf91',decimals:2}],{unit:'s'})}</div><div class="stats-grid equal">${chart('activity-first-seen',l('Ensimmäistä kertaa havaitut osoitteet','First-observed addresses'),l('Ensimmäinen havainto tässä indeksissä','First observation in this index'),p,[{key:'first_seen_native_addresses',label:'Native',color:'#82aef7'},{key:'first_seen_evm_addresses',label:'EVM',color:'#c6a3ef'}],{foot:l('Osittainen indeksi ei todista osoitteen syntymäaikaa. Vanhakin osoite voi olla tässä aineistossa ensimmäistä kertaa havaittu.','A partial index does not establish when an address was created. An old address may be first observed in this data.')})}${bars(l('Tapahtumalajien jakauma','Operation distribution'),l('Valittu aikaväli','Selected range'),state.data?.breakdown?.operations)}</div>`+note('Siirtovolyymia ei päätellä kaikkien ulostulojen summasta: mukana olisi myös vaihtorahaa ja sisäisiä siirtoja. Aktiivisuus kattaa indeksin ilmoittaman lohkoalueen.','Transfer volume is not inferred by adding all outputs: those include change and internal movements. Activity covers the block range stated by the index.');}
  function locationOf(node){const p=node?.location;if(!p||typeof p.latitude!=='number'||typeof p.longitude!=='number'||!Number.isFinite(p.latitude)||!Number.isFinite(p.longitude)||p.latitude< -90||p.latitude>90||p.longitude< -180||p.longitude>180)return null;return p;}
  function filteredNodes(){const q=state.search.trim().toLowerCase();return array(state.data?.nodes).filter(n=>n&&typeof n==='object').filter(n=>state.role==='all'||array(n.roles).includes(state.role)).filter(n=>!q||[n.id,n.status,n.location?.country,n.location?.city,...array(n.roles)].join(' ').toLowerCase().includes(q));}
  const endpointId=item=>typeof item?.id==='string'&&/^[a-f0-9]{16,128}$/i.test(item.id)?item.id:'';
  const endpointLabel=item=>l('Päätepiste','Endpoint')+(endpointId(item)?' '+shorten(endpointId(item),8):'');
  function filteredEndpoints(){const q=state.search.trim().toLowerCase();return state.role==='all'?array(state.data?.peer_endpoints).filter(p=>p&&typeof p==='object').filter(p=>!q||[endpointId(p),p.location?.country,p.location?.city].join(' ').toLowerCase().includes(q)):[];}
  function map(nodes){const located=nodes.filter(locationOf),unlocated=nodes.length-located.length,peers=filteredEndpoints().filter(locationOf);
    const grids=[-120,-60,0,60,120].map(lon=>`<line class="stats-map-grid" x1="${(lon+180)*960/360}" y1="0" x2="${(lon+180)*960/360}" y2="480"/>`).join('')+[-60,-30,0,30,60].map(lat=>`<line class="stats-map-grid" x1="0" y1="${(90-lat)*480/180}" x2="960" y2="${(90-lat)*480/180}"/>`).join('');
    return `<div class="stats-map-shell"><svg viewBox="0 0 960 480" role="img" aria-label="${esc(l('Havaittujen nodejen likimääräiset IP-sijainnit','Approximate IP locations of observed nodes'))}"><title>${esc(l('Havaitut nodet · IP-paikannus','Observed nodes · IP geolocation'))}</title>${grids}<image href="statistics/world-map.svg" width="960" height="480"/>${peers.map(peer=>{const loc=locationOf(peer),label=`${endpointLabel(peer)} · ${[loc.city,loc.country].filter(Boolean).join(', ')} · ${l('Identiteettiä ei vahvistettu','Identity unconfirmed')}`;return `<g tabindex="0" role="img" aria-label="${esc(label)}" class="stats-map-endpoint" transform="translate(${((loc.longitude+180)*960/360).toFixed(2)},${((90-loc.latitude)*480/180).toFixed(2)})"><title>${esc(label)}</title><circle class="stats-map-halo" r="12"/><path class="stats-map-core" d="M 0 -6 L 6 0 L 0 6 L -6 0 Z"/></g>`;}).join('')}${located.map(node=>{const loc=locationOf(node),idx=array(state.data.nodes).indexOf(node),isStorage=array(node.roles).includes('storage'),label=`${node.local?l('Oma node','This node')+' · ':''}${shorten(node.id)} · ${[loc.city,loc.country].filter(Boolean).join(', ')}`;return `<g tabindex="0" role="button" aria-label="${esc(label)}" data-select-node="${idx}" class="stats-map-marker${isStorage?' storage':''}${state.selected===node.id?' selected':''}" transform="translate(${((loc.longitude+180)*960/360).toFixed(2)},${((90-loc.latitude)*480/180).toFixed(2)})"><title>${esc(label)}</title><circle class="stats-map-halo" r="12"/><circle class="stats-map-core" r="5"/></g>`;}).join('')}</svg>${!located.length&&!peers.length?`<div class="stats-map-empty">${esc(l('Sijaintitietoja ei vielä ole.','No location data yet.'))}<br>${esc(l('Nodet näkyvät luettelossa.','Nodes remain visible in the list.'))}</div>`:''}<div class="stats-map-legend"><span><i></i>Witness</span><span><i class="storage"></i>Storage</span><span><i class="endpoint"></i>${esc(l('Päätepiste · tunnistamaton','Endpoint · unidentified'))}</span></div></div><div class="stats-map-coverage"><span><strong>${number(located.length)}</strong> ${esc(l('kartalla','on map'))} · <strong>${number(unlocated)}</strong> ${esc(l('ilman sijaintia','without location'))}${peers.length?' · '+number(peers.length)+' '+esc(l('verkkopäätepistettä kartalla','network endpoints on map')):''}</span><span>${esc(l('Likimääräinen IP-sijainti · Natural Earth','Approximate IP location · Natural Earth'))}</span></div>`;
  }
  function geoStatus(){
    const geo=state.data?.geolocation||{},dbip=geo.provider==='DB-IP'||[...array(state.data?.nodes),...array(state.data?.peer_endpoints)].some(n=>n?.location?.source==='dbip_city_lite');
    let message='';
    if(geo.status==='awaiting_download')message=l('GeoIP-aineiston ensimmäinen lataus on kesken. Sijainnit ilmestyvät seuraavien keruiden aikana.','The first GeoIP database download is pending. Locations will appear in subsequent collections.');
    else if(geo.status==='disabled')message=l('IP-sijaintihaku on poistettu käytöstä.','IP geolocation is disabled.');
    else if(geo.status==='error')message=l('Paikallista GeoIP-aineistoa ei voitu lukea. Tarkista aineiston ja päivityspalvelun tila.','The local GeoIP database could not be read. Check the database and update service.');
    else if(!geo.configured)message=l('Paikallinen GeoIP-aineisto puuttuu. Ota sijaintitiedot käyttöön palvelimella.','No local GeoIP database is configured. Enable location data on the server.');
    return `<div class="stats-geo-status">${dbip?`<span><a href="https://db-ip.com" target="_blank" rel="noopener noreferrer">IP Geolocation by DB-IP</a> · <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a></span><span>${esc(l('Aineiston päiväys','Database date'))}: <strong>${esc(geo.database_date||'—')}</strong>${geo.auto_update?' · '+esc(l('Automaattinen kuukausipäivitys','Automatic monthly updates')):''}</span>`:''}${message?`<span>${esc(message)}</span>`:''}${geo.database_stale?`<span class="stats-geo-warning">${esc(l('Sijaintiaineisto on yli 62 päivää vanha. Tarkista päivityspalvelu.','The location database is over 62 days old. Check the update service.'))}</span>`:''}${geo.update_status==='error'?`<span class="stats-geo-warning">${esc(geo.available?l('Viimeisin sijaintiaineiston päivitys epäonnistui. Paikallinen aineisto on edelleen käytössä.','The latest location database update failed. The local database remains in use.'):l('Sijaintiaineiston lataus epäonnistui. Tarkista päivityspalvelu.','The location database download failed. Check the update service.'))}</span>`:''}</div>`;
  }
  const rawInteger=value=>typeof value==='string'&&value.length<=100&&/^\d+$/.test(value)?BigInt(value):null;
  function shareBasisPoints(amount,total){return total>0n?amount*10000n/total:null;}
  function shareLabel(amount,total){const ratio=shareBasisPoints(amount,total);return ratio===null?'—':amount>0n&&ratio===0n?l('< 0,01 %','< 0.01 %'):number(Number(ratio)/100,2)+' %';}
  function shareWidth(amount,total){const ratio=shareBasisPoints(amount,total);return ratio===null?'0':(Number(ratio)/100).toFixed(2);}
  function walletLabel(value){const fp=String(value??'');return `<span class="stats-wallet" tabindex="0" role="img" aria-label="${esc(l('Lompakon sormenjälki','Wallet fingerprint')+' '+fp)}" title="${esc(fp)}">${esc(shorten(fp,14))}</span>`;}
  function delegationData(node){
    const d=node.delegation;if(!d||d.available!==true||d.source!=='local_committed_delegations'||typeof d.owner_fp!=='string'||!d.owner_fp||d.owner_fp.length>256||!Array.isArray(d.delegations))return null;
    const keys=['self_stake_raw','delegated_raw','owner_delegated_raw','external_delegated_raw','total_stake_raw'];
    const values=keys.map(key=>rawInteger(d[key]));if(values.some(v=>v===null))return null;
    const [self,delegated,owner,external,total]=values;
    const rows=[],seen=new Set();let sum=0n,ownerSum=0n;
    for(const row of d.delegations){
      const amount=rawInteger(row?.amount_raw);
      if(amount===null||typeof row.owner_fp!=='string'||!row.owner_fp||row.owner_fp.length>256||seen.has(row.owner_fp)||typeof row.is_owner!=='boolean'||row.is_owner!==(row.owner_fp===d.owner_fp))return null;
      seen.add(row.owner_fp);sum+=amount;if(row.is_owner)ownerSum+=amount;rows.push({...row,amount});
    }
    if(sum!==delegated||ownerSum!==owner||owner+external!==delegated||self+delegated!==total||d.delegator_count!==rows.length)return null;
    rows.sort((a,b)=>a.amount===b.amount?a.owner_fp.localeCompare(b.owner_fp):a.amount>b.amount?-1:1);
    return {d,rows,self,delegated,owner,external,total};
  }
  function delegationDetails(node){
    if(!array(node.roles).some(role=>role==='witness'||role==='validator'))return '';
    const data=delegationData(node),heading=l('Witnessin panokset ja delegoinnit','Witness stake and delegations');
    if(!data)return `<section class="stats-delegation" id="statistics-delegation-details"><h3>${esc(heading)}</h3>${empty(l('Delegointitietoja ei ole saatavilla','Delegation data is unavailable'),l('Vahvistettua delegointitilannetta ei ole vielä kerätty tälle witnessille. Puuttuvia tietoja ei näytetä nollana.','A verified delegation snapshot has not been collected for this witness yet. Missing values are not shown as zero.'))}</section>`;
    const {d,rows,self,delegated,owner,external,total}=data;
    const parts=[{label:l('Validaattorin oma panos','Validator self-stake'),amount:self,color:'#6edace'},{label:l('Omistajan delegointi','Owner delegation'),amount:owner,color:'#c6a3ef'},{label:l('Muiden delegoinnit','Other wallets’ delegations'),amount:external,color:'#82aef7'}];
    const readout=parts.map(part=>`${part.label}: ${rawAmount(String(part.amount))} NODUS · ${shareLabel(part.amount,total)}`).join('; ');
    const leaders=rows.slice(0,10).map(row=>({...row,label:row.owner_fp,other:false}));
    if(rows.length>10)leaders.push({amount:rows.slice(10).reduce((sum,row)=>sum+row.amount,0n),label:l('Muut delegoijat','Other delegators')+' ('+number(rows.length-10)+')',other:true});
    const pageCount=Math.max(1,Math.ceil(rows.length/25));state.delegationPage=Math.max(0,Math.min(state.delegationPage,pageCount-1));
    const page=state.delegationPage,visible=rows.slice(page*25,(page+1)*25);
    return `<section class="stats-delegation" id="statistics-delegation-details"><div class="stats-delegation-heading"><h3>${esc(heading)}</h3><span class="stats-panel-badge">${esc(l('Lohko','Block'))} ${esc(number(d.at_height))}</span></div><p class="stats-inline-note">${esc(l('Näytetään lompakoiden sormenjäljet, ei henkilöiden nimiä.','Wallet fingerprints are shown, not people’s names.'))}</p>${d.stale?`<p class="stats-geo-warning" role="status">${esc(l('Delegointihavainto on vanhentunut tai keruu on keskeytynyt.','The delegation snapshot is stale or collection has stopped.'))}</p>`:''}${d.lag_blocks>0?`<p class="stats-inline-note">${esc(l('Paikallinen delegointihavainto on verkon havaittua kärkeä jäljessä','The local delegation snapshot trails the observed network tip'))}: ${esc(number(d.lag_blocks))} ${esc(l('lohkoa','blocks'))}.</p>`:''}<div class="stats-delegation-owner"><span>${esc(l('Validaattorin omistajalompakko','Validator owner wallet'))}</span>${walletLabel(d.owner_fp)}</div><div class="stats-kpis stats-delegation-kpis">${metric(l('Oma panos','Self-stake'),rawAmount(d.self_stake_raw),'NODUS',true)}${metric(l('Delegoitu yhteensä','Total delegated'),rawAmount(d.delegated_raw),'NODUS')}${metric(l('Sidottu yhteensä','Total bonded'),rawAmount(d.total_stake_raw),'NODUS')}${metric(l('Delegoijalompakot','Delegating wallets'),number(rows.length),l('Sisältää omistajan delegoinnin','Includes owner delegation'))}</div><figure class="stats-stake-composition"><figcaption>${esc(l('Sidotun panoksen jakauma','Bonded stake composition'))}</figcaption>${total>0n?`<div class="stats-stake-stack" role="img" tabindex="0" aria-label="${esc(readout)}" title="${esc(readout)}">${parts.map(part=>`<span style="width:${shareWidth(part.amount,total)}%;background:${part.color}"></span>`).join('')}</div>`:`<p class="stats-inline-note">${esc(l('Ei sidottuja panoksia tässä havainnossa.','No bonded stake in this observation.'))}</p>`}<div class="stats-stake-legend">${parts.map(part=>`<div><span><i style="background:${part.color}"></i>${esc(part.label)}</span><strong>${esc(rawAmount(String(part.amount)))} NODUS</strong><small>${esc(shareLabel(part.amount,total))}</small></div>`).join('')}</div></figure><div class="stats-delegation-columns"><div class="stats-delegation-leaders"><h4>${esc(l('Suurimmat delegoinnit','Largest delegations'))}</h4><p class="stats-inline-note">${esc(l('Kymmenen suurinta ja muut yhteensä · osuudet delegoidusta summasta','Top ten and all others combined · shares of delegated stake'))}</p>${leaders.length?`<div class="stats-bars">${leaders.map((row,i)=>`<div class="stats-bar-row${row.other?' stats-delegator-others':''}"><div class="stats-bar-label"><span>${row.other?esc(row.label):walletLabel(row.label)}${row.is_owner?` <small>${esc(l('Omistaja','Owner'))}</small>`:''}</span><strong>${esc(rawAmount(String(row.amount)))} NODUS · ${esc(shareLabel(row.amount,delegated))}</strong></div><div class="stats-bar-track"><span style="width:${shareWidth(row.amount,delegated)}%;background:${row.other?'#b49ed4':row.is_owner?'#c6a3ef':'#82aef7'}"></span></div></div>`).join('')}</div>`:empty(l('Ei voimassa olevia delegointeja','No current delegations'),l('Tässä ketjuhavainnossa witnessille ei ole delegoitu panosta.','This chain observation contains no delegated stake for the witness.'))}</div><div class="stats-delegation-list"><h4>${esc(l('Kaikki delegoinnit','All delegations'))}</h4><div class="stats-table-wrap"><table class="stats-table stats-delegation-table"><thead><tr><th>${esc(l('Lompakon sormenjälki','Wallet fingerprint'))}</th><th>NODUS</th><th>${esc(l('Osuus delegoinneista','Share of delegations'))}</th></tr></thead><tbody>${visible.map(row=>`<tr><td>${walletLabel(row.owner_fp)}${row.is_owner?` <span class="stats-role">${esc(l('Omistaja','Owner'))}</span>`:''}</td><td class="mono">${esc(rawAmount(row.amount_raw))}</td><td class="mono">${esc(shareLabel(row.amount,delegated))}</td></tr>`).join('')}</tbody></table></div>${rows.length?`<div class="stats-delegation-pagination"><span>${esc(number(page*25+1))}–${esc(number(Math.min(rows.length,(page+1)*25)))} / ${esc(number(rows.length))}</span><div><button class="stats-refresh" id="statistics-delegation-prev"${page===0?' disabled':''}>${esc(l('Edellinen','Previous'))}</button><button class="stats-refresh" id="statistics-delegation-next"${page===pageCount-1?' disabled':''}>${esc(l('Seuraava','Next'))}</button></div></div>`:''}</div></div><p class="stats-delegation-source">${esc(l('Lähde: paikallinen vahvistettu ketjutila','Source: local committed chain state'))} · ${esc(l('Lohko','Block'))} ${esc(number(d.at_height))} · ${esc(l('Havaittu','Observed'))} ${esc(date(d.observed_at))}. ${esc(l('Paikallinen ketju voi olla verkon kärkeä jäljessä. Nykytilanne ei muutu tilaston aikavälivalinnalla.','The local chain may trail the network tip. This current snapshot does not change with the statistics range selector.'))}</p></section>`;
  }
  function nodeDetails(){const node=array(state.data?.nodes).find(n=>n.id===state.selected);if(!node)return '';const storage=node.storage||{},loc=locationOf(node);return `<section class="stats-panel stats-node-detail" id="statistics-node-details"><button class="stats-detail-close" id="statistics-close-node" aria-label="${esc(l('Sulje noden tiedot','Close node details'))}">×</button><h3>${esc(l('Noden tiedot','Node details'))}</h3><div class="stats-node-id">${esc(node.id)}</div>${facts([[l('Roolit','Roles'),array(node.roles).map(roleLabel).join(' · ')||'—'],[l('Tila','Status'),statusLabel(node.status)],[l('Viimeksi havaittu','Last observed'),date(node.last_seen)],[l('Sijainti','Location'),loc?[loc.city,loc.country].filter(Boolean).join(', '):l('Ei sijaintitietoa','No location data')],[l('Panostettu NODUS','Staked NODUS'),rawAmount(node.stake_raw)],[l('Äänivalta','Voting power'),number(node.power)],[l('Komissio','Commission'),node.commission_bps===null||node.commission_bps===undefined?'—':number(Number(node.commission_bps)/100,2)+' %'],...(array(node.roles).includes('storage')?[[l('Storage-virheputki','Storage fail streak'),number(storage.fail_streak)],[l('Grace päättyy · lohko','Grace ends · block'),number(storage.grace_until)],[l('Segmentit','Segments'),number(storage.segments??storage.n_segments)]]:[])])}<p class="stats-inline-note">${esc(l('Rekisterirooli tai komiteajäsenyys ei yksin todista verkkoyhteyden saatavuutta.','A registry role or committee membership alone does not prove network reachability.'))}</p>${delegationDetails(node)}</section>`;}
  function nodeList(nodes){return nodes.length?`<div class="stats-table-wrap"><table class="stats-table"><thead><tr><th>${esc(l('Node','Node'))}</th><th>${esc(l('Roolit','Roles'))}</th><th>${esc(l('Sijainti','Location'))}</th><th>${esc(l('Tila','Status'))}</th><th>${esc(l('Viimeksi havaittu','Last observed'))}</th></tr></thead><tbody>${nodes.slice(0,500).map(n=>{const index=array(state.data.nodes).indexOf(n),loc=locationOf(n);return `<tr${state.selected===n.id?' class="selected"':''}><td><button data-select-node="${index}" title="${esc(n.id)}">${esc(shorten(n.id))}</button>${n.local?` <span class="stats-role">${esc(l('Oma node','This node'))}</span>`:''}</td><td>${array(n.roles).map(r=>`<span class="stats-role${r==='storage'?' storage':''}">${esc(roleLabel(r))}</span>`).join('')}</td><td>${esc(loc?[loc.city,loc.country].filter(Boolean).join(', '):l('Ei sijaintitietoa','No location data'))}</td><td class="stats-status">${esc(statusLabel(n.status))}</td><td class="mono">${esc(date(n.last_seen,true))}</td></tr>`;}).join('')}</tbody></table></div>${nodes.length>500?`<div class="stats-table-note">${esc(l('Näytetään ensimmäiset 500 osumaa. Rajaa hakua.','Showing the first 500 matches. Refine the search.'))}</div>`:''}`:empty(l('Nodeja ei löytynyt','No nodes found'),l('Muuta hakua tai odota seuraavaa keruukertaa.','Change the filters or wait for the next collection.'));}
  function peerEndpointsView(){const endpoints=array(state.data?.peer_endpoints);if(!endpoints.length)return '';return `<section class="stats-panel" style="margin-top:18px">${panelHead(l('Havaitut verkkopäätepisteet','Observed network endpoints'),l('Paikallisen noden havainnot · nodeidentiteettiä ei vahvistettu','Observations from the local node · node identity is not confirmed'),number(summary().observed_endpoints??endpoints.length))}<div class="stats-table-wrap"><table class="stats-table"><thead><tr><th>${esc(l('Päätepiste','Endpoint'))}</th><th>${esc(l('Sijainti','Location'))}</th><th>${esc(l('Viimeksi havaittu','Last observed'))}</th></tr></thead><tbody>${endpoints.slice(0,256).map(item=>`<tr><td class="mono">${esc(endpointLabel(item))}</td><td>${esc(item.location?[item.location.city,item.location.country].filter(Boolean).join(', '):l('Ei sijaintitietoa','No location data'))}</td><td>${esc(date(item.last_seen,true))}</td></tr>`).join('')}</tbody></table></div><div class="stats-panel-foot">${esc(l('Päätepisteiden lukumäärää ei lisätä nodejen tunnistemäärään: useat osoitteet voivat kuulua samalle nodelle, eikä osoitetta ole sidottu identiteettiin.','Endpoint counts are not added to identified node counts: several addresses may belong to one node, and an endpoint has not been bound to an identity.'))}${state.data?.peer_observation?.truncated?' '+esc(l('Lähteen lista on rajattu.','The source list is truncated.')):''}</div></section>`;}
  function nodesView(){const s=summary(),nodes=filteredNodes();return `<div class="stats-kpis">${metric(l('Aktiiviset witnessit','Active witnesses'),number(s.active_validators),l('Komitean jäsenet','Committee members'),true)}${metric(l('Storage-nodet','Storage nodes'),number(s.storage_nodes),l('Nykyisen epochin jäsenet','Current epoch set members'))}${metric(l('Havaitut nodet','Observed nodes'),number(s.observed_nodes),l('Havaitut tunnisteet · ei online-luku','Observed identities · not an online count'))}${metric(l('Kartalla / suodatus','Mapped / filtered'),number(nodes.filter(locationOf).length),`${number(nodes.length)} ${l('nodea luettelossa','nodes in list')}`)}</div><section class="stats-panel">${panelHead(l('Havaitut nodet','Observed nodes'),l('Kartta ja nodehakemisto · likimääräiset sijainnit','Map and directory · approximate locations'))}<div class="stats-map-toolbar"><input id="statistics-node-search" class="stats-search" type="search" value="${esc(state.search)}" placeholder="${esc(l('Hae tunnisteella, maalla tai kaupungilla…','Search by identifier, country or city…'))}" aria-label="${esc(l('Hae nodeja','Search nodes'))}"><select id="statistics-role-filter" class="stats-filter" aria-label="${esc(l('Suodata roolin mukaan','Filter by role'))}">${[['all',l('Kaikki roolit','All roles')],['witness','Witness'],['storage','Storage']].map(([v,name])=>`<option value="${v}"${state.role===v?' selected':''}>${esc(name)}</option>`).join('')}</select></div><div id="statistics-node-results">${map(nodes)}${geoStatus()}${nodeList(nodes)}</div></section>${state.selected?`<div style="margin-top:18px">${nodeDetails()}</div>`:''}${peerEndpointsView()}`+note('Hakemisto kuvaa kerääjän havaitsemia nodeja. Se ei takaa koko hajautetun verkon kattavuutta. Sama node voi toimia useassa roolissa. IP-sijainti kuvaa palvelinta, ei sen omistajaa.','This directory describes nodes seen by the collector. It does not guarantee coverage of the entire decentralized network. One node can have several roles. An IP location describes a server, not its owner.');}
  function stakingView(){const s=summary();return `<div class="stats-kpis">${metric(l('Validaattorien omat panokset','Validator self-stake'),rawAmount(s.self_stake_raw),'NODUS',true)}${metric(l('Delegoitu NODUS','Delegated NODUS'),rawAmount(s.delegated_raw),l('Sidotuille validaattoreille','To bonded validators'))}${metric(l('Palkkiopooli','Reward pool'),rawAmount(s.reward_pool_raw),'NODUS')}${metric(l('Storage-nodet','Storage nodes'),number(s.storage_nodes),l('Nykyisen epochin jäsenet','Current epoch set members'))}</div><div class="stats-grid equal">${chart('staking-history',l('Sidotun NODUSin kehitys','Bonded NODUS over time'),l('Säännölliset verkkohavainnot','Periodic network observations'),network(),[{key:'self_stake_raw',label:l('Omat panokset','Self-stake'),color:'#6edace'},{key:'delegated_raw',label:l('Delegoinnit','Delegations'),color:'#82aef7'}],{raw:true,unit:'NODUS',gapMs:900000*(coverage().network_sample_stride||1)})}${chart('staking-nodes',l('Verkon roolit ajan myötä','Network roles over time'),l('Havaittu määrä keruukerroittain','Observed counts over time'),network(),[{key:'active_validators',label:'Witness',color:'#6edace'},{key:'storage_nodes',label:'Storage',color:'#bed68d'}],{gapMs:900000*(coverage().network_sample_stride||1)})}</div><div class="stats-grid equal">${bars(l('Treasury-poolit','Treasury pools'),l('Viimeisin ketjusta luettu tilanne','Latest chain observation'),state.data?.breakdown?.treasury,{raw:true})}<section class="stats-panel">${panelHead(l('Storage-roolien tila','Storage role status'),l('Rekisteriin tallennetut havainnot','Registry observations'))}${facts([[l('Storage-nodet','Storage nodes'),number(s.storage_nodes)],[l('Grace-jaksolla','In grace period'),number(s.storage_in_grace)],[l('Virheputki vähintään 3','Fail streak at least 3'),number(s.storage_failing)],[l('Poistumassa','Exiting'),number(s.storage_exiting)]])}<div class="stats-panel-foot">${esc(l('Rekisteri ei kerro koko verkon vapaata tai varattua levytilaa. Grace ja virheputki kuvaavat storage-roolia.','The registry does not report total free or allocated disk capacity across the network. Grace and fail streak describe the storage role.'))}</div></section></div>`;}
  function contractsView(){const p=activity(),contracts=array(state.data?.contracts);return `<div class="stats-grid equal">${chart('contracts-calls',l('Sopimusten käyttö','Contract activity'),l('Kutsut ja uudet julkaisut aikajaksoittain','Calls and deployments per time bucket'),p,[{key:'evm_calls',label:l('Kutsut','Calls'),color:'#82aef7'},{key:'evm_creates',label:l('Julkaisut','Deployments'),color:'#6edace'}])}${chart('contracts-failures',l('EVM-suoritusten epäonnistumiset','Failed EVM executions'),l('Ketjuun hyväksytyt, kulut maksaneet epäonnistumiset','Applied failed executions that paid a fee'),p,[{key:'evm_failed',label:l('Epäonnistuneet suoritukset','Failed executions'),color:'#e9b17d'},{key:'refused',label:l('Hylätyt tapahtumat','Refused transactions'),color:'#bd9ae3'}],{foot:l('Hylätty tapahtuma ja ketjuun hyväksytty epäonnistunut EVM-suoritus ovat eri asioita.','A refused transaction and an applied failed EVM execution are different outcomes.')})}</div><section class="stats-panel">${panelHead(l('Aktiiviset sopimukset','Active contracts'),l('Valitun aikavälin indeksoidut havainnot','Indexed observations in the selected range'))}${contracts.length?`<div class="stats-table-wrap"><table class="stats-table"><thead><tr><th>${esc(l('Sopimusosoite','Contract address'))}</th><th>${esc(l('Kutsut','Calls'))}</th><th>${esc(l('Käytetty gas','Gas used'))}</th><th>${esc(l('Epäonnistuneet','Failed'))}</th></tr></thead><tbody>${contracts.slice(0,100).map(c=>`<tr><td title="${esc(c.address)}"><span class="stats-contract-address">${esc(shorten(c.address,18))}</span></td><td>${esc(number(c.calls??c.count))}</td><td>${esc(number(c.gas_used))}</td><td>${esc(number(c.failed))}</td></tr>`).join('')}</tbody></table></div>`:empty(l('Sopimushavaintoja ei vielä ole','No contract observations yet'),l('Sopimukset tulevat näkyviin, kun niiden tapahtumat on indeksoitu.','Contracts appear when their transactions have been indexed.'))}</section>`;}
  function sources(){const c=coverage();return `<details class="stats-source-details"><summary>${esc(l('Lähteet, kattavuus ja laskentatapa','Sources, coverage and definitions'))}</summary>${facts([[l('Havaintohistoria alkaa','Observation history starts'),date(c.observations_from??c.observed_from)],[l('Indeksoitu lohkoalue','Indexed block range'),c.indexed_from_height===null||c.indexed_from_height===undefined?'—':`${number(c.indexed_from_height)} – ${number(c.indexed_to_height)}`],[l('Verkon havaittu kärki','Observed chain tip'),number(c.tip_height)],[l('Viimeisin keruu','Latest collection'),date(state.data?.observed_at??state.data?.generated_at)],[l('Ketjutunniste','Chain identifier'),state.data?.chain_id||'—']])}<ul><li>${esc(l('Aktiiviset osoitteet tarkoittavat ketjussa havaittuja osoitteita. Luvut eivät kerro ihmisten tai kaikkien luotujen lompakoiden määrää.','Active addresses are addresses observed on chain. Counts do not represent people or all created wallets.'))}</li><li>${esc(l('Tapahtumahistoria kattaa vain indeksoidut lohkot. Vanhoja verkkohavaintoja, saatavuutta tai sijainteja ei arvata jälkikäteen.','Transaction history covers indexed blocks only. Past network observations, availability and locations are not guessed.'))}</li><li>${esc(l('NODUS-summat näytetään kokonaislukuihin perustuvina desimaaleina. Käyrien pistearvot ovat tarkistettavissa osoittamalla tai näppäimistöllä.','NODUS amounts are displayed as integer-based decimals. Inspect chart values using a pointer or keyboard.'))}</li><li>${esc(l('Näytetyt ajat: Europe/Helsinki. Kartan pohja: Natural Earth, public domain.','Displayed times: Europe/Helsinki. Map outlines: Natural Earth, public domain.'))}</li></ul><a href="https://github.com/nocdem/dna/blob/main/explorer/README.md" target="_blank" rel="noopener noreferrer">${esc(l('Scanin rajapintakuvaus','Scan API reference'))}</a>${array(state.data?.errors).length?`<p>${esc(l('Tietolähteiden ilmoitukset','Source diagnostics'))}: <code>${esc(array(state.data.errors).map(e=>typeof e==='string'?e:e.source||e.code||l('Tietolähde ei saatavilla','Source unavailable')).join(' · '))}</code></p>`:''}</details>`;}
  function coverageBanner(){const c=coverage(),hasIndex=c.indexed_from_height!==null&&c.indexed_from_height!==undefined;let body='';if(state.data?.stale)body+=`<div class="stats-banner warning" role="status"><strong>${esc(l('Viimeisin keruu ei ole tuore.','The latest collection is stale.'))}</strong> ${esc(l('Näytetään viimeisin tallennettu havainto aikaleimoineen.','Showing the latest stored observation with its timestamp.'))}</div>`;
    const incomplete=c.range_complete===false||c.caught_up===false||c.complete===false||c.index_complete===false||(hasIndex&&Number(c.indexed_to_height)<Number(c.tip_height));
    if(state.data?.available===false)return body+`<div class="stats-banner warning" role="status"><strong>${esc(l('Tilastoaineistoa ei vielä ole saatavilla.','Statistics data is not available yet.'))}</strong> ${esc(l('Kerääjän ensimmäinen onnistunut havainto avaa tilastot. Tarkista tietolähteiden tila palvelimella.','The first successful collection enables statistics. Check the data sources on the server.'))}</div>`;
    if(incomplete||!hasIndex)body+=`<div class="stats-banner"><strong>${esc(l('Tapahtumahistoria on vielä osittainen.','Transaction history is still partial.'))}</strong> ${hasIndex?`${esc(l('Indeksoidut lohkot','Indexed blocks'))} ${number(c.indexed_from_height)}–${number(c.indexed_to_height)}${c.tip_height?` / ${number(c.tip_height)}`:''}. `:''}${esc(l('Osoite- ja sopimustilastot koskevat vain tätä aineistoa. Scanin 24 tunnin tapahtumakäyrä on erillinen lähde.','Address and contract statistics cover this data only. Scan’s 24-hour activity chart is a separate source.'))}</div>`;if(c.addresses_complete===false&&hasIndex)body+=`<div class="stats-banner">${esc(l('Osa lähtöosoitteista tai EVM-tiedoista puuttuu. Osoiteluvut kattavat tunnetut osoitteet; tuntemattomia arvoja ei korvata nollalla.','Some sender addresses or EVM facts are unavailable. Address counts cover known addresses; unknown values are not replaced with zero.'))}</div>`;return body;}
  function render(){if(!isActive())return;const data=state.data;root.innerHTML=`<section class="nodus-statistics" id="nodus-statistics"><div class="stats-heading"><div><span class="eyebrow">NODUS / ${esc(l('VERKKOTILASTOT','NETWORK STATISTICS'))}</span><h1>${esc(l('Verkko numeroina.','The network, in numbers.'))}</h1><p>${esc(l('Aktiivisuus, nodet ja ketjun kehitys samassa näkymässä.','Activity, nodes and chain history in one place.'))}</p></div><div class="stats-heading-meta"><strong><i class="stats-dot"></i>${esc(state.demo?l('ESIKATSELU','PREVIEW'):'NODUS TESTNET')}</strong>${esc(date(data?.observed_at??data?.generated_at))}</div></div><div class="stats-controls"><div class="stats-tabs" role="tablist" aria-label="${esc(l('Tilastonäkymä','Statistics view'))}">${tabs().map(([id,label])=>`<button class="stats-tab" role="tab" id="statistics-tab-${id}" data-stat-tab="${id}" aria-selected="${state.tab===id}" aria-controls="statistics-content">${esc(label)}</button>`).join('')}</div><div class="stats-toolbar-right"><div class="stats-ranges" role="group" aria-label="${esc(l('Tilastojen aikaväli','Statistics range'))}">${ranges().map(([id,label])=>`<button class="stats-range" data-stat-range="${id}" aria-pressed="${state.range===id}">${esc(label)}</button>`).join('')}</div><button class="stats-refresh" id="statistics-refresh"${state.loading?' disabled':''}>${esc(l('Päivitä','Refresh'))}</button><button class="stats-refresh" id="statistics-export"${state.demo||state.loading||state.exporting||!data?.available?' disabled':''}>${esc(state.exporting?l('Viedään…','Exporting…'):'CSV')}</button></div></div>${state.demo?`<div class="stats-banner preview" role="status"><strong>${esc(l('Synteettinen esikatselu','Synthetic preview'))}</strong> · ${esc(l('Luvut ja nodet ovat keksittyjä esimerkkejä kiinteältä 24 tunnin jaksolta.','Numbers and nodes are fictional examples from a fixed 24-hour interval.'))}</div>`:''}${state.exportError?`<div class="stats-banner error" role="alert">${esc(l('CSV-vienti epäonnistui. Yritä uudelleen.','CSV export failed. Try again.'))}</div>`:''}${state.error?`<div class="stats-banner error" role="alert"><strong>${esc(l('Tilastotietoja ei voitu hakea.','Statistics could not be loaded.'))}</strong> ${esc(data?l('Aiemmin ladatut tiedot säilyivät.','Previously loaded data has been retained.'):l('Tarkista kerääjän tila ja yritä uudelleen.','Check the collector and try again.'))}<button class="stats-refresh" id="statistics-retry">${esc(l('Yritä uudelleen','Try again'))}</button></div>`:''}${state.loading&&!data?`<div class="stats-loading" role="status"><span>${esc(l('Haetaan verkon tilastoja…','Loading network statistics…'))}</span></div>`:''}${data?`${coverageBanner()}<div id="statistics-content" role="tabpanel" aria-labelledby="statistics-tab-${state.tab}"${state.loading?' aria-busy="true"':''}>${({overview,activity:activityView,nodes:nodesView,staking:stakingView,contracts:contractsView}[state.tab]||overview)()}</div>${sources()}`:''}</section>`;bind();}
  function bind(){
    root.querySelectorAll('[data-stat-tab]').forEach(el=>{el.onclick=()=>{state.tab=el.dataset.statTab;render();};el.onkeydown=event=>{const ids=tabs().map(([id])=>id),current=ids.indexOf(state.tab);let next=null;if(event.key==='ArrowRight')next=ids[(current+1)%ids.length];if(event.key==='ArrowLeft')next=ids[(current+ids.length-1)%ids.length];if(event.key==='Home')next=ids[0];if(event.key==='End')next=ids.at(-1);if(next){event.preventDefault();state.tab=next;render();root.querySelector('#statistics-tab-'+next)?.focus();}};});
    root.querySelectorAll('[data-stat-range]').forEach(el=>el.onclick=()=>{if(state.range===el.dataset.statRange)return;state.range=el.dataset.statRange;state.selected=null;state.delegationPage=0;state.data=null;return load();});
    root.querySelectorAll('[data-chart-readout]').forEach(el=>{const show=()=>{const target=root.querySelector('#'+el.dataset.chartReadout+'-readout');if(target)target.textContent=el.dataset.value;};el.addEventListener('mouseenter',show);el.addEventListener('focus',show);});
    root.querySelectorAll('[data-select-node]').forEach(el=>{const select=()=>{const n=array(state.data?.nodes)[Number(el.dataset.selectNode)];if(!n)return;if(state.selected!==n.id)state.delegationPage=0;state.selected=n.id;render();root.querySelector('#statistics-node-details')?.scrollIntoView?.({block:'start'});};el.onclick=select;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select();}};});
    const search=root.querySelector('#statistics-node-search');if(search)search.oninput=()=>{state.search=search.value;const start=search.selectionStart;render();const next=root.querySelector('#statistics-node-search');next?.focus();if(typeof next?.setSelectionRange==='function'&&start!==null)next.setSelectionRange(start,start);};
    const filter=root.querySelector('#statistics-role-filter');if(filter){filter.value=state.role;filter.onchange=()=>{state.role=filter.value;render();};}
    const close=root.querySelector('#statistics-close-node');if(close)close.onclick=()=>{state.selected=null;state.delegationPage=0;render();};
    const previous=root.querySelector('#statistics-delegation-prev');if(previous)previous.onclick=()=>{state.delegationPage=Math.max(0,state.delegationPage-1);render();};
    const next=root.querySelector('#statistics-delegation-next');if(next)next.onclick=()=>{state.delegationPage++;render();};
    const refresh=root.querySelector('#statistics-refresh');if(refresh)refresh.onclick=()=>load();
    const exportButton=root.querySelector('#statistics-export');if(exportButton)exportButton.onclick=()=>exportCsv();
    const retry=root.querySelector('#statistics-retry');if(retry)retry.onclick=()=>load();
  }
  async function exportCsv(){
    if(state.demo||state.exporting||!state.data?.available)return;state.exporting=true;state.exportError=false;render();const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),10000);
    try{const response=await fetch(`/api/statistics/export.csv?range=${encodeURIComponent(state.range)}`,{cache:'no-store',signal:controller.signal});if(!response.ok)throw Error('export');const blob=await response.blob();const url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download=`nodus-statistics-${state.range}.csv`;document.body.appendChild(anchor);anchor.click();anchor.remove();URL.revokeObjectURL(url);}catch{state.exportError=true;}finally{clearTimeout(timer);state.exporting=false;render();}
  }
  async function load(){
    const id=++requestId;request?.abort();clearTimeout(refreshTimer);request=new AbortController();const controller=request;state.loading=true;state.error=false;render();
    const timer=setTimeout(()=>controller.abort(),10000);
    try{
      const url=state.demo?'statistics/preview.json':`/api/statistics?range=${encodeURIComponent(state.range)}`;
      const response=await fetch(url,{cache:'no-store',signal:controller.signal});if(!response.ok)throw Error('statistics_unavailable');
      const data=await response.json();if(!data||typeof data!=='object'||data.schema_version!==1||typeof data.available!=='boolean'||(state.demo&&data.preview!==true)||(!state.demo&&data.preview===true))throw Error('statistics_invalid');
      if(id!==requestId)return;state.data=data;state.dataRange=state.range;
    }catch{if(id===requestId)state.error=true;}
    finally{clearTimeout(timer);if(id===requestId){state.loading=false;request=null;render();if(isActive()&&!state.demo)refreshTimer=setTimeout(()=>{if(isActive())void load();},60000);}}
  }
  function mount(target,nextOptions={}){const modeChanged=state.demo!==(nextOptions.demo===true),targetChanged=root!==target;root=target;options=nextOptions;state.demo=nextOptions.demo===true;if(modeChanged){state.data=null;state.error=false;state.dataRange=null;}render();if(modeChanged||targetChanged&&!state.loading||!state.data&&!state.loading&&!state.error||nextOptions.refresh===true&&!state.loading)void load();else if(targetChanged)render();}
  function unmount(){requestId++;request?.abort();request=null;clearTimeout(refreshTimer);state.loading=false;root=null;}
  globalThis.addEventListener?.('languagechange',()=>render());
  globalThis.addEventListener?.('hashchange',()=>{if(globalThis.location?.hash!=='#statistics')unmount();});
  globalThis.NodusStatistics={mount,unmount,refresh:load,helpers:{rawAmount,locationOf,escape:esc},getState:()=>({tab:state.tab,range:state.range,loading:state.loading,error:state.error,demo:state.demo})};
})();
